// Runner configuration. Edit runner_mode to switch selection behavior.
//   first_pass_domain_diversity (DEFAULT) — max 1 selected URL per normalized domain per run.
//   deep_domain_analysis            — allow multiple URLs per domain (cap 3/domain/run), explicit.
// Both modes always keep: max_per_run=5, url_registry runtime recheck, exact normalized-URL dedup,
// manual handoff to Workflow 04, no auto-call, no auto-mark processed.
const runner_mode = 'first_pass_domain_diversity';
return [{ json: { runner_mode: runner_mode } }];

// Single source of truth for selection. Reads url_candidates rows AND RE-READS url_registry
// at runtime. candidate_url is RE-NORMALIZED with the SAME rules as Workflow 04/05 and verified
// to NOT already exist in url_registry before selection. Editable dedup_status / registry_status
// in url_candidates are advisory discovery-time hints only and are NOT trusted.
//
// runner_mode (from "Set Runner Config"):
//   first_pass_domain_diversity (DEFAULT) — max 1 selected URL per normalized domain per run;
//       extra approved same-domain URLs are skipped with reason_category=duplicate_domain_in_run.
//   deep_domain_analysis — multiple approved URLs per domain allowed intentionally, capped at 3
//       per domain per run; extras beyond 3 skipped with reason_category=domain_deep_limit;
//       selected items carry a deep-mode warning.
// BOTH modes ALWAYS enforce: url_registry runtime recheck, exact normalized-URL dedup, and the
// hard cap max_per_run=5. url_registry semantics are UNCHANGED (full normalized URL, not domain).
const rows = $('Read url_candidates').all().map(i => i.json).filter(Boolean);

// Re-read url_registry (source of truth for dedup) and build a set of normalized URLs.
let registry = [];
try { registry = $('Read url_registry').all().map(i => i.json).filter(Boolean); } catch (e) { registry = []; }
const regSet = new Set(registry.map(r => String(r.normalized_source_url || '').trim()).filter(Boolean));

// Runner config (default first_pass_domain_diversity).
let runner_mode = 'first_pass_domain_diversity';
try {
  const cfg = $('Set Runner Config').first().json || {};
  const m = String(cfg.runner_mode || '').trim().toLowerCase();
  if (m === 'deep_domain_analysis' || m === 'first_pass_domain_diversity') runner_mode = m;
} catch (e) { /* keep default */ }
const DEEP = (runner_mode === 'deep_domain_analysis');
const PER_DOMAIN_CAP = DEEP ? 3 : 1; // deep: max 3 URLs/domain/run; first-pass: max 1/domain/run

function pad(n){ return String(n).padStart(2, '0'); }
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const now = moscowIsoNow();
const stamp = moscowStamp();
const run_id = 'approved_run_' + stamp;
const MAX = 5; // HARD CAP: max 5 approved URLs per run (both modes)

function str(v){ return (v==null?'':String(v)).trim(); }
function lc(v){ return str(v).toLowerCase(); }

// URL normalizer — SAME rules as Workflow 04/05 (keys must match url_registry).
function normalizeUrl(u){
  u = String(u || '').trim();
  if (!u) return '';
  try {
    const noFrag = u.split('#')[0];
    const url = new URL(noFrag);
    url.protocol = (url.protocol || '').toLowerCase();
    url.hostname = (url.hostname || '').toLowerCase();
    const drop = ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','gclid','yclid','fbclid'];
    for (const p of drop) url.searchParams.delete(p);
    let path = url.pathname || '/';
    if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
    url.pathname = path;
    return url.toString();
  } catch (e) { return u; }
}

// Domain extractor from candidate_url — SAME rules as Workflow 05 (hostname, lowercase, strip leading www).
function extractDomain(u){
  let h = '';
  try { h = new URL(String(u||'').trim()).hostname; } catch (e) { h = ''; }
  if (!h) { const m = String(u||'').match(/^https?:\/\/([^\/?#]+)/i); h = m ? m[1] : ''; }
  h = h.toLowerCase();
  if (h.indexOf('www.') === 0) h = h.slice(4);
  return h;
}

// Root homepage detection (path empty or '/') — used as a priority tiebreaker.
function isRootUrl(u){
  try { const p = new URL(String(u||'').trim()).pathname || '/'; return (p === '' || p === '/'); } catch (e) { return false; }
}

// Non-direct-competitor types are allowed when approved, but flagged with a warning.
const NON_DIRECT = ['aggregator','directory','marketplace','social','media_article'];

const evaluated = [];
for (const r of rows){
  // Skip fully blank rows (alwaysOutputData can emit an empty item on an empty sheet).
  if (!str(r.candidate_id) && !str(r.candidate_url)) continue;

  const approval = lc(r.approval_status);
  const url = str(r.candidate_url);
  const ctype = lc(r.candidate_type);
  const normalized = normalizeUrl(url); // re-normalized at runtime; stored field is NOT trusted
  const domain = extractDomain(normalized || url); // re-derived from candidate_url, not from stored domain
  const isRoot = isRootUrl(normalized || url);

  let eligible = true; let skip_category = ''; let skip_reason = '';
  if (approval === 'processed'){ eligible=false; skip_category='already_processed'; skip_reason='approval_status=processed (already handed off)'; }
  else if (approval === 'duplicate' || approval === 'rejected' || approval === 'error'){ eligible=false; skip_category='duplicate_status'; skip_reason='approval_status=' + approval + ' (not eligible)'; }
  else if (approval !== 'approved'){ eligible=false; skip_category='approval_status_not_approved'; skip_reason='approval_status=' + (approval||'empty') + ' (need approved)'; }
  else if (url === ''){ eligible=false; skip_category='missing_candidate_url'; skip_reason='candidate_url empty'; }
  else if (normalized !== '' && regSet.has(normalized)){ eligible=false; skip_category='registry_recheck_duplicate'; skip_reason='registry_recheck_duplicate: normalized_source_url already exists in url_registry (editable dedup_status/registry_status ignored)'; }

  const warning = (eligible && NON_DIRECT.includes(ctype))
    ? 'not_direct_competitor_optional_warning: candidate_type is not direct_competitor; review before Workflow 04.'
    : '';

  evaluated.push({ row:r, eligible, skip_category, skip_reason, warning, ctype, url, normalized, domain, isRoot,
    confidence: parseInt(r.confidence_score)||0,
    rank: parseInt(r.rank)||999 });
}

// Prioritize eligible: direct_competitor first, higher confidence, lower rank, then root homepage first.
const eligibleList = evaluated.filter(e => e.eligible);
eligibleList.sort((a,b)=>{
  const ad = a.ctype==='direct_competitor'?0:1;
  const bd = b.ctype==='direct_competitor'?0:1;
  if (ad!==bd) return ad-bd;
  if (b.confidence!==a.confidence) return b.confidence-a.confidence;
  if (a.rank!==b.rank) return a.rank-b.rank;
  const ar = a.isRoot?0:1; const br = b.isRoot?0:1;
  return ar-br;
});

// Select in priority order, enforcing the per-domain cap (mode-dependent) and the overall hard cap.
let batch_index = 0;
let selectedCount = 0;
const domainCounts = {}; // domain -> selected count this run
for (let i=0;i<eligibleList.length;i++){
  const e = eligibleList[i];
  const dom = e.domain;
  const dcount = dom ? (domainCounts[dom]||0) : 0;
  if (dom && dcount >= PER_DOMAIN_CAP){
    e._selected = false;
    if (DEEP){
      e._skip_category = 'domain_deep_limit';
      e._skip_reason = 'domain_deep_limit: more than ' + PER_DOMAIN_CAP + ' approved URLs from domain ' + dom + ' in deep_domain_analysis mode; extra skipped.';
    } else {
      e._skip_category = 'duplicate_domain_in_run';
      e._skip_reason = 'Same domain already selected in this run; use deep_domain_analysis mode for multi-page domain analysis.';
    }
    continue;
  }
  if (selectedCount >= MAX){
    e._selected = false;
    e._skip_category = 'over_limit';
    e._skip_reason = 'over_limit (eligible but exceeds max_per_run=5; approve in a later run)';
    continue;
  }
  e._selected = true; selectedCount++; batch_index++; e._batch_index = batch_index;
  if (dom) domainCounts[dom] = (domainCounts[dom]||0) + 1;
  if (DEEP) e._deep_warning = 'deep_domain_analysis mode: multiple URLs from same domain allowed intentionally.';
}

const out = [];
for (const e of evaluated){
  const r = e.row;
  const isSel = (e._selected === true);
  const skip_category = isSel ? '' : (e._skip_category || e.skip_category);
  const skip = isSel ? '' : (e._skip_reason || e.skip_reason);
  const warning = [e.warning || '', (isSel && e._deep_warning) ? e._deep_warning : ''].filter(Boolean).join(' | ');
  out.push({ json: {
    candidate_id: str(r.candidate_id),
    discovery_request_id: str(r.discovery_request_id),
    candidate_url: e.url,
    normalized_source_url: e.normalized,
    stored_normalized_source_url: str(r.normalized_source_url),
    domain: e.domain,
    is_root: e.isRoot,
    candidate_type: str(r.candidate_type),
    confidence_score: e.confidence,
    rank: e.rank,
    approval_status: str(r.approval_status),
    dedup_status: str(r.dedup_status),
    registry_status: str(r.registry_status),
    approved_by: str(r.approved_by),
    approved_at: str(r.approved_at),
    service_hint: str(r.service_hint),
    region_hint: str(r.region_hint),
    notes: str(r.notes),
    runner_mode: runner_mode,
    warning: warning,
    _selected: isSel,
    _confirm_processed: (skip_category==='registry_recheck_duplicate'), // approved + now in url_registry => WF04 processed it (safe, idempotent)
    _eligible: e.eligible,
    _skip_category: skip_category,
    _skip_reason: skip,
    run_id: run_id,
    batch_index: isSel ? e._batch_index : 0,
    target_url: isSel ? e.url : '',
    source_type: 'scraped_web',
    platform: 'website',
    source_candidate_id: str(r.candidate_id),
    parsed_at: now,
    source_note: 'approved_candidates_runner',
    force_reprocess: false
  }});
}
return out;

// One summary item per run. Aggregates the annotated rows from the selection node.
const all = $('Select, Prioritize & Annotate').all().map(i => i.json);
const selected = all.filter(r => r._selected === true);
const skipped = all.filter(r => r._selected !== true);
const run_id = (all[0] && all[0].run_id) || '';
const runner_mode = (all[0] && all[0].runner_mode) || 'first_pass_domain_diversity';
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
const now = moscowIsoNow();

const selected_urls = selected.map(r => r.candidate_url);
const selected_domains = Array.from(new Set(selected.map(r => r.domain).filter(Boolean)));
const domain_selected_counts = {};
for (const r of selected){ if (r.domain){ domain_selected_counts[r.domain] = (domain_selected_counts[r.domain]||0) + 1; } }

const handoff_lines = selected_urls.map(function(u){ return "  '" + u + "',"; }).join('\n');
const set_url_list_block = 'const rawUrls = [\n' + handoff_lines + '\n];';

const domain_diversity = (runner_mode === 'deep_domain_analysis')
  ? 'deep_domain_analysis: multiple URLs per domain allowed intentionally (cap 3/domain/run); extras skipped as domain_deep_limit. url_registry semantics unchanged.'
  : 'first_pass_domain_diversity (default): max 1 URL per domain per run; second+ URL from a selected domain skipped as duplicate_domain_in_run. url_registry semantics unchanged.';

return [{ json: {
  workflow: '06 - Approved Candidates Runner',
  run_id: run_id,
  generated_at: now,
  total_candidates_read: all.length,
  selected_count: selected.length,
  skipped_count: skipped.length,
  max_per_run: 5,
  runner_mode: runner_mode,
  processing_mode: 'manual_handoff_to_workflow_04',
  registry_recheck: 'enabled: url_registry re-read at runtime, candidate_url re-normalized; editable dedup_status/registry_status are advisory only',
  domain_diversity: domain_diversity,
  domain_selected_counts: domain_selected_counts,
  selected_domains: selected_domains,
  selected_urls: selected_urls,
  selected: selected.map(function(r){ return { batch_index:r.batch_index, candidate_id:r.candidate_id, candidate_url:r.candidate_url, normalized_source_url:r.normalized_source_url, domain:r.domain, is_root:r.is_root, candidate_type:r.candidate_type, confidence_score:r.confidence_score, rank:r.rank, service_hint:r.service_hint, discovery_request_id:r.discovery_request_id, warning:r.warning }; }),
  skipped: skipped.map(function(r){ return { candidate_id:r.candidate_id, candidate_url:r.candidate_url, domain:r.domain, candidate_type:r.candidate_type, reason_category:r._skip_category, reason:r._skip_reason }; }),
  workflow_04_set_url_list_block: set_url_list_block,
  operator_note: (selected.length === 0)
    ? 'No eligible candidates after runtime registry recheck. Approve at least one direct_competitor candidate whose normalized URL is NOT already in url_registry, then re-run.'
    : 'Copy the URLs above into Workflow 04 -> Set URL List (max 5), run Workflow 04. Marking processed is AUTOMATIC and SAFE: the enabled "Mark Candidates Processed (confirmed in url_registry)" node sets approval_status=processed ONLY for approved candidates whose normalized_source_url now appears in url_registry (i.e. WF04 actually wrote them). It never marks skipped/failed candidates and never marks freshly-selected handoffs (they stay approved until confirmed). Idempotent: re-running WF06 after WF04 confirms + marks; already-processed rows are skipped. Flow: approve -> WF06 (handoff) -> run WF04 -> re-run WF06 (auto-confirm + mark). runner_mode=' + runner_mode + '. Items carrying a warning need review before Workflow 04.'
}}];
